INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(54011, 'Job 14:12', 'Job', 14, 12, 'نو انسان په قبر کښې څملى او بيا نۀ راپاڅى، چې ترڅو پورې آسمانونه ختم شوى نۀ وى، نو هغوئ به د خپل خوب نه نۀ راپاڅى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_12.mp3', '', 1761754199, 1761754199),
(54012, 'Job 14:13', 'Job', 14, 13, 'کاش، چې تا زۀ په قبر کښې پټ کړے وے، او چې تر هغې پورې دې زۀ فنا کړے وے چې ستا غصه تېره شوے وے، او يا دې يو وخت مقرر کړے وے چې زۀ دې راپه ياد شوے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_13.mp3', '', 1761754199, 1761754199),
(54013, 'Job 14:14', 'Job', 14, 14, 'چې انسان ختم شى، نو هغه بيا ژوندے کېدے شى څۀ؟ زۀ به زما د سخت محنت په دې ټولو ورځو کښې اِنتظار کوم تر هغې پورې چې زما تکليف ختم شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_14.mp3', '', 1761754199, 1761754199),
(54014, 'Job 14:15', 'Job', 14, 15, 'تۀ به ما ته آواز وکړې او زۀ به جواب درکړم، تۀ به د هغه مخلوق ارمان وکړې چې تا پېدا کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_15.mp3', '', 1761754199, 1761754199),
(54015, 'Job 14:16', 'Job', 14, 16, 'بيا به تۀ زما په هر قدم باندې نظر ساتې، خو زما د ګناهونو حساب به نۀ کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_16.mp3', '', 1761754199, 1761754199),
(54016, 'Job 14:17', 'Job', 14, 17, 'زما ګناهونه به په يوه بوجۍ کښې بند شوې وى، او تۀ به زما ټولې غلطيانې پټې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_17.mp3', '', 1761754199, 1761754199),
(54017, 'Job 14:18', 'Job', 14, 18, 'خو غر راوغورزيږى او ټوټې ټوټې شى، او غټ غټ کاڼى د خپل ځائ نه وخوځيږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_18.mp3', '', 1761754199, 1761754199),
(54018, 'Job 14:19', 'Job', 14, 19, 'اوبۀ کاڼى مږى، او سېلاب د زمکې خاوره اوړى، نو داسې تۀ د انسان اُميد تباه کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_19.mp3', '', 1761754199, 1761754199),
(54019, 'Job 14:20', 'Job', 14, 20, 'تۀ په هغوئ باندې تل غالب يې او هغوئ ختميږى، تۀ د هغوئ شکلونه بدلوې او د مرګ په طرف يې بوځې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_20.mp3', '', 1761754199, 1761754199),
(54020, 'Job 14:21', 'Job', 14, 21, 'کۀ د هغۀ بچو ته عزت مِلاو شى، نو هغۀ ته پته نۀ لګى، او کۀ د هغۀ د بچو سپکاوے وشى نو هم هغۀ ته پته نۀ لګى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_21.mp3', '', 1761754199, 1761754199),
(54021, 'Job 14:22', 'Job', 14, 22, 'هغۀ ته صِرف د خپل بدن درد محسوسيږى، او هغه صرف په خپل غم کښې آخته وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job14_verse_22.mp3', '', 1761754199, 1761754199),
(54022, 'Genesis 11:1', 'Genesis', 11, 1, 'په هغه وخت کې د ټولې نړۍ خلکو یوه ژبه درلودله او یو قسم خبرې به یې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_1.mp3', '', 1761754199, 1761754199),
(54023, 'Genesis 11:2', 'Genesis', 11, 2, 'خو وروسته هغوی د ختیځ خواته کډه وکړه او د شنعار په ځمکه کې یې یو هوار ځای پیدا کړ او هلته اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_2.mp3', '', 1761754199, 1761754199),
(54024, 'Genesis 11:3', 'Genesis', 11, 3, 'هغوی یو بل ته وویل: «راځئ چې خښتې جوړې کړو او هغه ښې پخې کړو.» هغوی د تیږو په ځای خښتې او د مسالې په ځای د قیر نه کار واخیست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_3.mp3', '', 1761754199, 1761754199),
(54025, 'Genesis 11:4', 'Genesis', 11, 4, 'هغوی وویل: «راځئ چې د خپل ځان دپاره یو ښار ودان کړو او په هغه کې یو لوړ برج جوړ کړو چې سر یې اسمان ته ورسیږي، ترڅو د خپل ځان دپاره یو نوم وګټو، داسې نه شي چې په ټوله دنیا کې خپاره شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_4.mp3', '', 1761754199, 1761754199),
(54026, 'Genesis 11:5', 'Genesis', 11, 5, 'خو کله چې څښتن راښکته شو چې هغه ښار او برج چې خلکو جوړ کړی ؤ وګوري،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_5.mp3', '', 1761754199, 1761754199),
(54027, 'Genesis 11:6', 'Genesis', 11, 6, 'هغه وویل: «اوس هغوی یو قوم دی او په یوه ژبه خبرې کوي. دا یوازې د کار پیل دی. هغوی به ډېر زر د دې توان پیدا کړي چې هرڅه وغواړي هغه به سرته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_6.mp3', '', 1761754199, 1761754199),
(54028, 'Genesis 11:7', 'Genesis', 11, 7, 'راځئ چې ښکته شو او د هغوی ژبه سره ګډه وډه کړو، ترڅو دوی یو د بل په خبرو باندې پوه نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_7.mp3', '', 1761754199, 1761754199),
(54029, 'Genesis 11:8', 'Genesis', 11, 8, 'نو څښتن هغوی په ټوله دنیا کې خپاره کړل او هغوی مجبور شول چې د ښار د جوړولو څخه لاس واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_8.mp3', '', 1761754199, 1761754199),
(54030, 'Genesis 11:9', 'Genesis', 11, 9, 'په دې سبب هغه ځای د بابل په نوم یاد شو، ځکه چې څښتن هلته د هغوی ژبه ګډه وډه کړه او هغوی یې په ټوله دنیا کې خپاره کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_9.mp3', '', 1761754199, 1761754199),
(54031, 'Genesis 11:10', 'Genesis', 11, 10, 'دا د سام اولاده ده: د سېلاب څخه دوه کاله وروسته هغه وخت چې سام د سلو کالو په عمر ؤ، د هغه زوی ارفکشاد پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_10.mp3', '', 1761754199, 1761754199),
(54032, 'Genesis 11:11', 'Genesis', 11, 11, 'د آرفکشاد د پیدا کېدلو څخه وروسته سام پنځه سوه کاله نور هم ژوند وکړ او نور اولادونه یې پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_11.mp3', '', 1761754199, 1761754199),
(54033, 'Genesis 11:12', 'Genesis', 11, 12, 'ارفکشاد د پنځه دېرشو کالو په عمر ؤ چې د هغه زوی شالح پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_12.mp3', '', 1761754199, 1761754199),
(54034, 'Genesis 11:13', 'Genesis', 11, 13, 'د شالح د پیدا کېدلو څخه وروسته ارفکشاد څلور سوه درې کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_13.mp3', '', 1761754199, 1761754199),
(54035, 'Genesis 11:14', 'Genesis', 11, 14, 'هغه وخت چې شالح د دېرشو کالو په عمر ؤ د هغه زوی عیبر پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_14.mp3', '', 1761754199, 1761754199),
(54036, 'Genesis 11:15', 'Genesis', 11, 15, 'له هغې وروسته، شالح څلور سوه درې کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_15.mp3', '', 1761754199, 1761754199),
(54037, 'Genesis 11:16', 'Genesis', 11, 16, 'عیبر د څلوردېرشو کالو په عمر ؤ چې د هغه زوی فالج پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_16.mp3', '', 1761754199, 1761754199),
(54038, 'Genesis 11:17', 'Genesis', 11, 17, 'کله چې فالج پیدا شو، عیبر څلور سوه دېرش کاله نور هم ژوند وکړ او زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_17.mp3', '', 1761754199, 1761754199),
(54039, 'Genesis 11:18', 'Genesis', 11, 18, 'فالج د دېرشو کالو په عمر ؤ چې د هغه زوی رعو پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_18.mp3', '', 1761754199, 1761754199),
(54040, 'Genesis 11:19', 'Genesis', 11, 19, 'د رعو د پیدا کېدلو څخه وروسته فالج دوه سوه نهه کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_19.mp3', '', 1761754199, 1761754199),
(54041, 'Genesis 11:20', 'Genesis', 11, 20, 'رعو د دوه دېرشو کالو په عمر ؤ چې د هغه زوی سروج پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_20.mp3', '', 1761754199, 1761754199),
(54042, 'Genesis 11:21', 'Genesis', 11, 21, 'د سروج د پیدا کېدلو څخه وروسته رعو دوه سوه اووه کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_21.mp3', '', 1761754199, 1761754199),
(54043, 'Genesis 11:22', 'Genesis', 11, 22, 'سروج د دېرشو کالو په عمر ؤ چې د هغه زوی ناحور پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_22.mp3', '', 1761754199, 1761754199),
(54044, 'Genesis 11:23', 'Genesis', 11, 23, 'د ناحور د پیدا کېدلو څخه وروسته سروج دوه سوه کاله ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_23.mp3', '', 1761754199, 1761754199),
(54045, 'Genesis 11:24', 'Genesis', 11, 24, 'ناحور د نهه ویشتو کالو په عمر ؤ چې د هغه زوی تارح پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_24.mp3', '', 1761754199, 1761754199),
(54046, 'Genesis 11:25', 'Genesis', 11, 25, 'د تارح د پیدا کېدلو څخه وروسته ناحور یوسلو نولس کاله نور هم ژوند وکړ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_25.mp3', '', 1761754199, 1761754199),
(54047, 'Genesis 11:26', 'Genesis', 11, 26, 'وروسته له دې چې تارح د اویا کالو په عمر شو، د هغه زامن ابرام، ناحور او هاران پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_26.mp3', '', 1761754199, 1761754199),
(54048, 'Genesis 11:27', 'Genesis', 11, 27, 'دا د تارح اولاده ده چې د هغه څخه ابرام، ناحور او هاران پیدا شول. هاران د لوط پلار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_27.mp3', '', 1761754199, 1761754199),
(54049, 'Genesis 11:28', 'Genesis', 11, 28, 'د هاران پلار لا ژوندی ؤ چې هغه خپل د زېږېدلو په ځای یعنې د کلدانیانو د اور په ښار کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_28.mp3', '', 1761754199, 1761754199),
(54050, 'Genesis 11:29', 'Genesis', 11, 29, 'ابرام د سارای سره واده وکړ او ناحور د میلکه سره چې د هاران لور وه، واده وکړ. هاران د یسکا پلار هم ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_29.mp3', '', 1761754199, 1761754199),
(54051, 'Genesis 11:30', 'Genesis', 11, 30, 'سارای شنډه وه او ماشومان یې نه درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_30.mp3', '', 1761754199, 1761754199),
(54052, 'Genesis 11:31', 'Genesis', 11, 31, 'تارح خپل زوی ابرام، خپل لمسی لوط چې د هاران زوی ؤ او د هغه انږور یعنې د ابرام ښځه سارای د ځان سره واخیستل او د کلدانیانو د اور د ښار څخه ووتل چې د کنعان خاورې ته لاړ شي. خو کله چې هغوی حران ته راغلل، نو هلته پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_31.mp3', '', 1761754199, 1761754199),
(54053, 'Genesis 11:32', 'Genesis', 11, 32, 'تارح د دوه سوه پنځو کالو په عمر په حران کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis11_verse_32.mp3', '', 1761754199, 1761754199),
(54054, 'Ruth 1:3', 'Ruth', 1, 3, 'الیملک مړ شو او نعومي د خپلو دوو زامنو سره یوازې پاتې شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_3.mp3', '', 1761754199, 1761754199),
(54055, 'Ruth 1:4', 'Ruth', 1, 4, 'وروسته د نعومي زامنو موآبي ښځې وکړې. د یوې نوم عرفه او د بلې نوم روت ؤ. وروسته له هغې چې هغوی هلته نژدې لس کاله اوسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_4.mp3', '', 1761754199, 1761754199),
(54056, 'Ruth 1:5', 'Ruth', 1, 5, 'محلون او کیلون هم مړه شول. نو اوس نعومي مېړه او زامن دواړه نه درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_5.mp3', '', 1761754199, 1761754199),
(54057, 'Ruth 1:8', 'Ruth', 1, 8, 'نعومي خپلو دواړو انږورګانو ته وویل: «ځئ هره یوه د خپلو میندو کورونو ته لاړې شئ، زما څښتن دې په تاسو مهربانه شي لکه څنګه چې تاسو په ما او زما په مړو زامنو باندې مهرباني وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_8.mp3', '', 1761754199, 1761754199),
(54058, 'Ruth 1:9', 'Ruth', 1, 9, 'خدای دې تاسو هرې یوې ته بل مېړه او کور درکړي.» نعومي دوی ښکل کړې. هغوی په لوړ اواز سره وژړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_9.mp3', '', 1761754199, 1761754199),
(54059, 'Ruth 1:10', 'Ruth', 1, 10, 'او ویې ویل: «نه، مونږ غواړو چې ستا سره لاړې شو او ستا د خلکو په منځ کې واوسو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_10.mp3', '', 1761754199, 1761754199),
(54060, 'Ruth 1:11', 'Ruth', 1, 11, 'خو نعومي په ځواب کې وویل: «زما لورګانو، تاسو ولې خپلو کورونو ته نه ستنېږئ؟ زما سره ستاسو تګ تاسو ته څه ګټه رسوي؟ تاسو فکر کوئ چې زه به نور زامن راوړم، ترڅو د هغوی سره تاسو ودونه وکړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_11.mp3', '', 1761754199, 1761754199),
(54061, 'Ruth 1:12', 'Ruth', 1, 12, 'بېرته کور ته لاړې شئ زما لورګانو، ځکه چې زه ډېره زړه یم او بیا د واده کولو وړ نه یم. حتی که چېرې زه نن شپه هم واده شم او زامن وزېږوم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_12.mp3', '', 1761754199, 1761754199),
(54062, 'Ruth 1:13', 'Ruth', 1, 13, 'نو ایا تاسو به هغوی ته صبر وکړئ چې هغوی ځلمیان شي او تاسو سره واده وکړي؟ نه، زما لورګانو! ژوند زما دپاره ستاسو په پرتله ډېر سخت دی، ځکه چې څښتن اوس په ما دا سخته راوستې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_13.mp3', '', 1761754199, 1761754199),
(54063, 'Ruth 1:14', 'Ruth', 1, 14, 'دوی بیا وژړل او عرفې خپله خواښې د خدای پامانۍ په وخت کې ښکل کړه، خو روت د هغې لمن پرېنښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_14.mp3', '', 1761754199, 1761754199),
(54064, 'Ruth 1:15', 'Ruth', 1, 15, 'نعومي بیا روت ته وویل: «ګوره ستا یور بېرته خپلو خلکو او خپل خدای ته ځي! ته ولې هغې سره نه ځې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_15.mp3', '', 1761754199, 1761754199),
(54065, 'Ruth 1:16', 'Ruth', 1, 16, 'روت په ځواب کې وویل: «ماته مه وایه چې تا پرېږدم او کور ته ستنه شم! زه به هلته ځم چېرته چې ته ځې او زه به هلته اوسېږم چېرته چې ته اوسېږې. ستا خلک به زما خلک وي او ستا خدای به زما خدای وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_16.mp3', '', 1761754199, 1761754199),
(54066, 'Ruth 1:17', 'Ruth', 1, 17, 'زه به هلته مړه کېږم چېرته چې ته مړه کېږې او هلته به ښخېږم. څښتن دې ماته د ټولو نه درنده سزا راکړي که چېرې د مرګ نه پرته سره بېل شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_17.mp3', '', 1761754199, 1761754199),
(54067, 'Ruth 1:18', 'Ruth', 1, 18, 'کله چې نعومي ولیدل چې روت کلکه اراده کړې چې د هغې سره لاړه شي، نو نعومي هغه نوره مجبوره نه کړه چې بېرته موآب ته لاړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_18.mp3', '', 1761754199, 1761754199),
(54068, 'Ruth 1:19', 'Ruth', 1, 19, 'هغوی دواړه بیت لحم ته ورسېدلې او د ټول ښار خلک خوشحاله شول او ښځو د یو بل څخه وپوښتل: «ایا دا په رښتیا نعومي ده؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_19.mp3', '', 1761754199, 1761754199),
(54069, 'Ruth 1:20', 'Ruth', 1, 20, 'بیا هغې دوی ته وویل: «له دې وروسته ما نعومي مه بولئ! ما ماره بولئ، ځکه چې مطلق قادر خدای زما ژوند تریخ کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_20.mp3', '', 1761754199, 1761754199),
(54070, 'Ruth 1:21', 'Ruth', 1, 21, 'کله چې زه لاړم نو ما هرڅه درلودل، خو څښتن زه بېرته تش لاس راوستلې یم. څنګه تاسو کولای شئ بیاهم ما نعومي وبولئ؟ اوس مطلق قادر څښتن زما په ضد شوی دی او زما ژوند یې ډېر سخت کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_21.mp3', '', 1761754199, 1761754199),
(54071, 'Ruth 1:22', 'Ruth', 1, 22, 'نو په دې ډول نعومي د خپلې موآبي انږور سره د موآب څخه بېرته راغله. دوی په داسې حال کې بیت لحم ته راورسېدلې چې د اوربشو لو په پیل کېدلو ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth1_verse_22.mp3', '', 1761754199, 1761754199),
(54072, 'Genesis 26:1', 'Genesis', 26, 1, 'په هغه وطن کې برسېره په هغې قحطۍ باندې چې پخوا د ابراهیم په وخت کې راغلې وه، بله قحطي هم راغله. اسحاق د فلسطینیانو پاچا ابي‌ملک ته چې په جرار کې ؤ، ورغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_1.mp3', '', 1761754199, 1761754199),
(54073, 'Genesis 26:2', 'Genesis', 26, 2, 'څښتن اسحاق ته ښکاره شو او ویې ویل: «مصر ته مه ځه. په همدې وطن کې په هغه ځای کې چې زه یې درته وایم، اوسېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_2.mp3', '', 1761754199, 1761754199),
(54074, 'Genesis 26:3', 'Genesis', 26, 3, 'همدلته اوسېږه. زه به ستا سره مل یم او برکت به درکړم. زه به تا او ستا اولادې ته دا ټوله سیمه درکړم او په هغې وعدې باندې به ټینګ ولاړ یم چې ستا د پلار ابراهیم سره مې کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_3.mp3', '', 1761754199, 1761754199),
(54075, 'Genesis 26:4', 'Genesis', 26, 4, 'ستا اولاده به د اسمان د ستورو په شان زیاته کړم او هغوی ته به دا ټوله سیمه ورکړم. ستا د اولادې په وسیله به د ځمکې په مخ ټول قومونه برکت ومومي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_4.mp3', '', 1761754199, 1761754199),
(54076, 'Genesis 26:5', 'Genesis', 26, 5, 'ځکه چې ابراهیم زما اطاعت کړی دی او زما په ټولو حکمونو او قوانینو باندې یې عمل کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_5.mp3', '', 1761754199, 1761754199),
(54077, 'Genesis 26:6', 'Genesis', 26, 6, 'نو اسحاق په جرار کې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_6.mp3', '', 1761754199, 1761754199),
(54078, 'Genesis 26:7', 'Genesis', 26, 7, 'کله چې د هغه ځای خلکو د اسحاق څخه د ربکا په اړه پوښتنه وکړه، هغه وویل: «هغه زما خور ده.» ځکه هغه وېرېده چې داسې ووایي چې هغه زما ښځه ده. هغه فکر کاوه چې د هغه ځای خلک به هغه د ربکا په خاطر ووژني، ځکه چې هغه ډېره ښکلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_7.mp3', '', 1761754199, 1761754199),
(54079, 'Genesis 26:8', 'Genesis', 26, 8, 'څرنګه چې اسحاق هلته زیات وخت تېر کړ، نو ابي‌ملک د فلسطینیانو پاچا د کړکۍ څخه لاندې وکتل او ویې لیدل چې اسحاق خپله ښځه ربکا په غېږ کې نیولې وه او هغه یې ښکلوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_8.mp3', '', 1761754199, 1761754199),
(54080, 'Genesis 26:9', 'Genesis', 26, 9, 'نو ابي‌ملک اسحاق راوغوښت او ورته ویې ویل: «هغه په رښتیا سره ستا ښځه ده! نو ولې دې وویل چې هغه ستا خور ده؟» اسحاق ځواب ورکړ: «ما فکر وکړ چې کېدای شي د هغې په خاطر ووژل شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_9.mp3', '', 1761754199, 1761754199),
(54081, 'Genesis 26:10', 'Genesis', 26, 10, 'ابي‌ملک وویل: «تا زمونږ سره څه وکړل؟ کېدای شو چې زما د کسانو څخه کوم یو ستا د ښځې سره څملاستلی وای او مونږ به دې ګناهکار کړي وای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_10.mp3', '', 1761754199, 1761754199),
(54082, 'Genesis 26:11', 'Genesis', 26, 11, 'ابي‌ملک ټولو خلکو ته خبرداری ورکړ: «که هرڅوک د دې سړي یا دې ښځې سره بد چلند وکړي هغه به ووژل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_11.mp3', '', 1761754199, 1761754199),
(54083, 'Genesis 26:12', 'Genesis', 26, 12, 'اسحاق په هغې ځمکې کې فصل وکاره او په هغه کال یې چې څه کرلي وو د هغې څخه یې یو په سل حاصل واخیست، ځکه چې څښتن هغه ته برکت ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_12.mp3', '', 1761754199, 1761754199),
(54084, 'Genesis 26:13', 'Genesis', 26, 13, 'اسحاق ورځ په ورځ نېکمرغه کېده او هغه ډېر شتمن سړی شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_13.mp3', '', 1761754199, 1761754199),
(54085, 'Genesis 26:14', 'Genesis', 26, 14, 'هغه دومره زیاتې رمې، پادې او غلامان درلودل چې فلسطینیانو ورباندې بخیلي کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_14.mp3', '', 1761754199, 1761754199),
(54086, 'Genesis 26:15', 'Genesis', 26, 15, 'نو هغه ټولې څاګانې چې د هغه د پلار ابراهیم غلامانو د هغه د پلار په وخت کې کیندلې وې، فلسطینیانو هغه د خاورو څخه ډکې کړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_15.mp3', '', 1761754199, 1761754199),
(54087, 'Genesis 26:16', 'Genesis', 26, 16, 'نو بیا ابي‌ملک اسحاق ته وویل: «ته زمونږ څخه ډېر قوي شوی یې، نو زمونږ د وطن څخه لاړ شه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_16.mp3', '', 1761754199, 1761754199),
(54088, 'Genesis 26:17', 'Genesis', 26, 17, 'نو اسحاق د هغه ځای څخه لاړ او د جرار په دره کې یې خېمې ودرولې او هلته پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_17.mp3', '', 1761754199, 1761754199),
(54089, 'Genesis 26:18', 'Genesis', 26, 18, 'اسحاق هغه څاګانې چې د هغه د پلار ابراهیم په وخت کې کیندل شوې وې او فلسطینیانو هغه د ابراهیم د مرګ څخه وروسته بندې کړې وې، بېرته وکیندلې او هماغه نومونه یې ورباندې کېښودل چې پلار یې ورباندې ایښي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_18.mp3', '', 1761754199, 1761754199),
(54090, 'Genesis 26:19', 'Genesis', 26, 19, 'د اسحاق غلامانو په دې دره کې یوه څاه وکیندله چې تازه اوبه یې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_19.mp3', '', 1761754199, 1761754199),
(54091, 'Genesis 26:20', 'Genesis', 26, 20, 'خو د جرار شپنو د اسحاق د شپنو سره دعوه پیل کړه او ویې ویل: «دا زمونږ اوبه دي!» نو اسحاق هغه څاه د عسق یعنې دعوې په نوم یاده کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_20.mp3', '', 1761754199, 1761754199),
(54092, 'Genesis 26:21', 'Genesis', 26, 21, 'د اسحاق غلامانو بله څاه وکیندله او په هغې باندې یې هم دعوه وکړه او هغه یې د سیتنه په نوم یاده کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_21.mp3', '', 1761754199, 1761754199),
(54093, 'Genesis 26:22', 'Genesis', 26, 22, 'او له هغه ځای څخه یې کډه وکړه او بله څاه یې وکیندله، خو په هغې باندې چا دعوه ونه کړه او هغه یې د رحوبوت په نوم یاده کړه او ویې ویل: «اوس څښتن مونږ ته ځای راکړی دی او په دې خاوره کې به نېکمرغه شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_22.mp3', '', 1761754199, 1761754199),
(54094, 'Genesis 26:23', 'Genesis', 26, 23, 'اسحاق له هغه ځای څخه بیرشبع ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_23.mp3', '', 1761754199, 1761754199),
(54095, 'Genesis 26:24', 'Genesis', 26, 24, 'په هماغه شپه څښتن هغه ته ښکاره شو او ورته ویې ویل: «زه ستا د پلار ابراهیم خدای یم. مه وېرېږه، ځکه چې زه ستا سره مل یم او برکت به درکړم او ستا اولاده به د خپل خدمتګار ابراهیم په خاطر زیاته کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_24.mp3', '', 1761754199, 1761754199),
(54096, 'Genesis 26:25', 'Genesis', 26, 25, 'اسحاق هلته د قربانۍ ځای جوړ کړ او د څښتن عبادت یې وکړ. بیا یې په هغه ځای کې خپلې خېمې ودرولې او د هغه غلامانو هلته یوه بله څاه وکیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_25.mp3', '', 1761754199, 1761754199),
(54097, 'Genesis 26:26', 'Genesis', 26, 26, 'یوه ورځ ابي‌ملک د خپل مشاور احوزات او د خپلو لښکرو د مشر فیکول سره د جرار څخه د اسحاق د لیدلو دپاره راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_26.mp3', '', 1761754199, 1761754199),
(54098, 'Genesis 26:27', 'Genesis', 26, 27, 'اسحاق د هغوی څخه پوښتنه وکړه: «تاسو خو زما سره دښمني کوله او زه مو د خپل وطن څخه وشړلم. نو اوس ولې زما د لیدلو دپاره راغلي یئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_27.mp3', '', 1761754199, 1761754199),
(54099, 'Genesis 26:28', 'Genesis', 26, 28, 'هغوی ځواب ورکړ: «مونږ ولیدل چې څښتن په رښتیا ستا سره مل دی، نو مونږ وویل چې زمونږ او ستاسو ترمنځ دې داسې یو قوي تړون وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_28.mp3', '', 1761754199, 1761754199),
(54100, 'Genesis 26:29', 'Genesis', 26, 29, 'چې مونږ ته زیان راونه رسوئ، لکه څنګه چې مونږ زیان نه دی دررسولی، بلکې ستا سره مو ښه چلند کړی دی او ته مو په سلامتۍ سره لېږلی یې. اوس څښتن برکت درکړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_29.mp3', '', 1761754199, 1761754199),
(54101, 'Genesis 26:30', 'Genesis', 26, 30, 'اسحاق د هغوی دپاره مېلمستیا تیاره کړه او هغوی وخوړل او وڅښل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_30.mp3', '', 1761754199, 1761754199),
(54102, 'Genesis 26:31', 'Genesis', 26, 31, 'سهار وختي هغوی پاڅېدل او یو بل ته یې قسم ورکړ. اسحاق هغوی رخصت کړل او په سلامتۍ سره د هغه څخه لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_31.mp3', '', 1761754199, 1761754199),
(54103, 'Genesis 26:32', 'Genesis', 26, 32, 'په هماغه ورځ د اسحاق غلامان راغلل او هغه ته یې د هغې څاه په اړه خبر ورکړ چې دوی کیندلې وه. هغوی وویل: «مونږ اوبه وموندلې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_32.mp3', '', 1761754199, 1761754199),
(54104, 'Genesis 26:33', 'Genesis', 26, 33, 'نو هغه یې د شبع په نوم یاده کړه. تر نن ورځې پورې هغه ښار د بیرشبع په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_33.mp3', '', 1761754199, 1761754199),
(54105, 'Genesis 26:34', 'Genesis', 26, 34, 'کله چې عیسو څلوېښت کلن شو، د بیري حیتي د لور یودیه او د ایلون حیتي لور بسمې سره یې واده وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_34.mp3', '', 1761754199, 1761754199),
(54106, 'Genesis 26:35', 'Genesis', 26, 35, 'خو هغوی د اسحاق او ربکا ژوند تریخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis26_verse_35.mp3', '', 1761754199, 1761754199),
(54107, 'Joshua 6:1', 'Joshua', 6, 1, 'د اریحا خلکو د اسراییلیانو له وېرې د ښار دروازې کلکې وتړلې او د هغه ساتنه کېدله. هېچا نه شو کولای چې ښار ته ننوځي یا د ښار څخه ووځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_1.mp3', '', 1761754199, 1761754199),
(54108, 'Joshua 6:2', 'Joshua', 6, 2, 'څښتن یوشع ته وویل: «زه اریحا د هغه د پاچا او د هغه د زړورو عسکرو سره تاته تسلیموم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_2.mp3', '', 1761754199, 1761754199),
(54109, 'Joshua 6:3', 'Joshua', 6, 3, 'ته او ستا عسکر باید شپږ ورځې د ورځې یوځل د ښار څخه ګردچاپېره وګرځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_3.mp3', '', 1761754199, 1761754199),
(54110, 'Joshua 6:4', 'Joshua', 6, 4, 'اووه کاهنان چې د هر یو سره سرنی وي هغوی دې د لوظ د صندوق په مخکې روان شي. په اوومه ورځ په داسې حال کې چې کاهنان به خپل سرني ووهي، تاسو ټول اووه ځله د ښار څخه ګردچاپېره وګرځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_4.mp3', '', 1761754199, 1761754199);